def drive(me, enemy, arena):
    # Calculate the distance and bearing to the enemy
    distance = distance_to(enemy.x, enemy.y)
    bearing = bearing_to(enemy.x, enemy.y)

    # If the enemy is in front and not too far, move forward
    if abs(bearing) < 45 and distance < 4 and me.speed < 0.3:
        return (1.0, 1.0)
    # If the enemy is behind, move backward
    elif abs(bearing) > 135 and distance < 4 and me.speed < 0.3:
        return (-0.5, -0.5)
    # Otherwise, try to maneuver to get a better position
    else:
        # Turn towards the enemy
        turn = cos(radians(bearing))
        return (turn, turn)

